import{z as A,x as p,o as E,c as B,q as o,j as n,D as e,d as t,s as l,S as i,b as r}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"2:4 结构稀疏","description":"","frontmatter":{"title":"2:4 结构稀疏","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/two-four-sparsity.md","filePath":"llm/two-four-sparsity.md","lastUpdated":1791063341000}'),d={name:"llm/two-four-sparsity.md"};function m(D,a,h,u,C,F){const s=p("Mermaid");return E(),B("div",null,[a[2]||(a[2]=o('<h1 id="_2-4-结构稀疏" tabindex="-1">2:4 结构稀疏 <a class="header-anchor" href="#_2-4-结构稀疏" aria-label="Permalink to &quot;2:4 结构稀疏&quot;">​</a></h1><div class="epigraph"><p>每四个连续权重里恰好两个为零。这不是又一种打分，是 Ampere 稀疏 Tensor Core 认得的模式；掩码对了，吞吐才有机会翻倍。</p><footer>—— Mishra et al., Accelerating Sparse Deep Neural Networks, 2021；SparseGPT / Wanda 均可在选择阶段加 N:M 约束</footer></div><p><a href="/llm/wanda">上一课</a> 给出元素分数，默认掩码任意。<a href="/llm/unstructured-sparsity">非结构化稀疏</a> 已经把「研究表稀疏 vs 墙钟」劈开。本课补硬件合同：<strong>N:M</strong>，LLM 上最常见的是 2:4。缺口是把 SparseGPT / Wanda 的选择器加上模式约束，而不是剪完再硬塞零。后课 Sheared LLaMA 把删除单位抬到层与通道，走另一条加速账。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>NVIDIA Ampere 起，稀疏 Tensor Core 要求沿输入通道每 4 个元素 2 个非零（2:4），才能走标称 2× 的 MMA 吞吐。50% 非结构稀疏在计数上同密度，在核上仍是密矩阵：索引不规则，Tensor Core 不接。问题变成：在 2:4 可行集里选哪两个留下，使层输出误差最小。可行集比非结构小得多，质量通常略差；换来的是<strong>有核就不只省存储</strong>。</p><p><span class="marginnote">数字实例：一组 4 个权重选 2 个留下，可能 pattern 只有 \\(\\binom{4}{2}=6\\) 种——就像每四个车位固定留两个空位。正因为 pattern 少且规整，硬件才能把它们编成固定指令，这是「非结构化 50% 做不到」的根本原因。</span></p><p>不要把 2:4 与「通道剪枝 50%」混报。通道剪枝留下的是更瘦的密 GEMM，任意 GPU 都能加速；2:4 留下原形状，只改内部模式，没有对应核就零加速。</p><p><span class="marginnote">Hopper 仍支持 2:4。没有稀疏 Tensor Core 的加速器上，2:4 只是一种正则化的掩码，不要写进吞吐对比。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>在 Wanda 分数或 SparseGPT 的重建目标上，对每个长度为 4 的窗口只保留分数最高（或补偿后最不疼）的 2 个。SparseGPT 论文明确支持把 N:M 写进选择阶段。剪完必须用稀疏核或至少用密×掩码模拟验收质量；报加速必须在真实 2:4 kernel 上测，含 dequant / 反稀疏开销。</p><p>与量化叠：先 2:4 再 GPTQ，或联合选格子与掩码，校准都要走真实掩码前向。宣传「4-bit × 2:4 = 8×」是连乘禁令，量化基础课已经写过。</p>',11)),(E(),n(i,null,{default:e(()=>[l(s,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E5%85%83%E7%B4%A0%E5%88%86%E6%95%B0%E6%88%96%20Hessian%22%5D%20--%3E%20WIN%5B%22%E6%AF%8F%204%20%E9%80%89%202%22%5D%0A%20%20WIN%20--%3E%20M%5B%222%3A4%20%E6%8E%A9%E7%A0%81%22%5D%0A%20%20M%20--%3E%20K%7B%22%E6%9C%89%E7%A8%80%E7%96%8F%20Tensor%20Core%3F%22%7D%0A%20%20K%20--%3E%7C%E6%98%AF%7C%20FAST%5B%22MMA%20%E5%90%9E%E5%90%90%E5%8F%AF%E7%BF%BB%E5%80%8D%22%5D%0A%20%20K%20--%3E%7C%E5%90%A6%7C%20STOR%5B%22%E5%8F%AA%E5%89%A9%E5%AD%98%E5%82%A8%E5%BD%A2%E6%80%81%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("h2",{id:"机制",tabindex:"-1"},[t("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=r("p",null,"2:4 把每组 4 个权重的组合从 \\(\\binom{4}{k}_{\\text{任意}}\\) 收到 \\(\\binom{4}{2}=6\\) 种模式。误差的不可补偿分量变大，所以同等 50% 下 PPL 通常高于非结构。补偿（SparseGPT）比纯 Wanda 更能把留下的 2 个值挪到减少重建误差的位置——2:4 下补偿的相对价值往往比非结构更大，因为自由度更少。",-1)),a[5]||(a[5]=r("p",null,"Decode 小 batch 时，瓶颈常在权重加载。2:4 若真按一半字节加载，带宽墙场景也能收益；若实现先展开成密 FP16 再乘，收益消失。要看的是加载路径，不是 MMA 宣传。",-1)),(E(),n(i,null,{default:e(()=>[l(s,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20H%5B%22%E5%90%8C%E6%A0%B7%E5%89%AA%E6%8E%89%2050%25%20%E6%9D%83%E9%87%8D%22%5D%20--%3E%20U%5B%22%E9%9D%9E%E7%BB%93%E6%9E%84%E5%8C%96%EF%BC%9A%E4%BD%8D%E7%BD%AE%E4%BB%BB%E6%84%8F%22%5D%0A%20%20H%20--%3E%20S%5B%222%3A4%EF%BC%9A%E6%AF%8F%204%20%E4%B8%AA%E7%95%99%202%22%5D%0A%20%20H%20--%3E%20C%5B%22%E9%80%9A%E9%81%93%E5%89%AA%E6%9E%9D%EF%BC%9A%E6%95%B4%E5%88%97%E5%88%A0%E9%99%A4%22%5D%0A%20%20U%20--%3E%20U1%5B%22%E5%BD%A2%E7%8A%B6%E4%B8%8D%E5%8F%98%20%C2%B7%20%E7%B4%A2%E5%BC%95%E6%97%A0%E8%A7%84%E5%BE%8B%20%C2%B7%20Tensor%20Core%20%E4%B8%8D%E6%8E%A5%22%5D%0A%20%20S%20--%3E%20S1%5B%22%E5%BD%A2%E7%8A%B6%E4%B8%8D%E5%8F%98%20%C2%B7%20%E6%A8%A1%E5%BC%8F%E5%9B%BA%E5%AE%9A%20%C2%B7%20%E7%A8%80%E7%96%8F%20MMA%20%E5%8F%AF%E7%BF%BB%E5%80%8D%22%5D%0A%20%20C%20--%3E%20C1%5B%22%E7%9F%A9%E9%98%B5%E5%8F%98%E7%98%A6%20%C2%B7%20%E4%BB%BB%E6%84%8F%20GPU%20%E5%AF%86%20GEMM%20%E6%8F%90%E9%80%9F%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=o('<p><span class="marginnote">数字实例：7B 模型的权重按 FP16 存约 14 GB。带宽受限的小 batch decode 里，权重流量是主账单——2:4 只有在加载路径真的只读一半字节（约 7 GB）时才谈得上接近 2 倍；展开成密矩阵再算，这 7 GB 一个字节也省不下来。</span></p><p><span class="marginnote">常见误区：初学者容易以为「剪掉一半权重 = 快一倍」。加速成立要同时满足三个条件：掩码符合硬件认识的模式、有对应的稀疏核、加载路径真省了字节。缺任何一条，2:4 就退化成一种省存储的正则化。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要在选完非结构掩码后再最近邻投影到 2:4，质量会掉一截。不要对 embedding / lm_head 盲目 2:4，词表行的模式与隐藏层不同，且核支持差。下一课结构化剪枝的 LLM 实例：Sheared LLaMA 直接改架构宽度，不依赖稀疏核。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>2:4 是硬件模式，不是新的重要性分数。</li><li>选择必须在 N:M 约束内做；事后投影会丢质量。</li><li>无稀疏 Tensor Core 则不要报 2×。</li><li>禁止与量化 bit 连乘成加速比。</li><li>出处：Mishra et al., 2021；Frantar &amp; Alistarh, SparseGPT；Sun et al., Wanda。</li></ul>',6))])}const c=A(d,[["render",m]]);export{_ as __pageData,c as default};
